package repofacts

import (
	"bytes"
	"path"
	"regexp"
)

// The header basis (RF-3): a file that says in its own first lines that a
// tool wrote it. Two forms are read, both generated:
//
//   - Go's generated-code line (https://go.dev/s/generatedcode), exactly
//     `// Code generated ... DO NOT EDIT.`, before the package clause, in a
//     Go file;
//   - the ADR-063 O6 kit provenance header: a comment line in the first
//     lines of any file that names the generator ("generated by <source>")
//     and either forbids hand edits or names the regeneration command
//     (`<!-- Code generated by cmd/kit-catalog; DO NOT EDIT. Regenerate:
//     task docs-index -->`, `# Code generated by env-kit from env.cue; DO
//     NOT EDIT.`).

// HeaderBytes is how many leading bytes of a file the header basis reads.
const HeaderBytes = 4096

// provenanceLines is how many leading lines may carry the O6 header.
const provenanceLines = 5

var (
	goGeneratedLine = regexp.MustCompile(`^// Code generated .* DO NOT EDIT\.$`)
	provenanceLine  = regexp.MustCompile(`(?i)^(?://|#|--|;|/\*|\*|<!--|\{\{/\*|%)\s*(?:this file (?:is|was)\s+)?(?:code\s+)?(?:auto-?)?generated\s+by\s+\S.*\b(?:do not edit|regenerate)`)
)

func headerRole(rel, dialect string, header []byte) (RoleName, bool) {
	if len(header) == 0 {
		return "", false
	}
	if len(header) > HeaderBytes {
		header = header[:HeaderBytes]
	}
	if dialect == "go" || path.Ext(rel) == ".go" {
		for _, line := range bytes.Split(header, []byte("\n")) {
			line = bytes.TrimRight(line, "\r")
			if goGeneratedLine.Match(line) {
				return Generated, true
			}
			if bytes.HasPrefix(line, []byte("package ")) {
				break
			}
		}
	}
	for i, line := range bytes.SplitN(header, []byte("\n"), provenanceLines+1) {
		if i == provenanceLines {
			break
		}
		if provenanceLine.Match(bytes.TrimSpace(line)) {
			return Generated, true
		}
	}
	return "", false
}
